import { Request, Response } from 'express';
import { PlaceOrderUseCase } from '../application/PlaceOrderUseCase';
import { UpdateOrderStateUseCase } from '../application/UpdateOrderStateUseCase';
import { CancelOrderUseCase } from '../application/CancelOrderUseCase';
import { ListOrdersByStateUseCase } from '../application/ListOrdersByStateUseCase';
import { OrderState } from '../domain/Order';
import { CreateOrderRequest } from '../application/DTOs';

export class OrderController {
  constructor(
    private placeOrderUseCase: PlaceOrderUseCase,
    private updateOrderStateUseCase: UpdateOrderStateUseCase,
    private cancelOrderUseCase: CancelOrderUseCase,
    private listOrdersByStateUseCase: ListOrdersByStateUseCase
  ) {}

  placeOrder = (req: Request, res: Response): void => {
    try {
      const request: CreateOrderRequest = req.body;
      const response = this.placeOrderUseCase.execute(request);
      res.status(201).json(response);
    } catch (error) {
      const message = error instanceof Error ? error.message : 'Unknown error';
      res.status(400).json({ error: message });
    }
  };

  updateOrderState = (req: Request, res: Response): void => {
    try {
      const orderId = Array.isArray(req.params.orderId) ? req.params.orderId[0] : req.params.orderId;
      const { state } = req.body;

      if (!state || !['paid', 'packed', 'shipped', 'delivered'].includes(state)) {
        res.status(400).json({ error: 'Invalid state' });
        return;
      }

      const response = this.updateOrderStateUseCase.execute(orderId, state as OrderState);
      res.json(response);
    } catch (error) {
      const message = error instanceof Error ? error.message : 'Unknown error';
      res.status(400).json({ error: message });
    }
  };

  cancelOrder = (req: Request, res: Response): void => {
    try {
      const orderId = Array.isArray(req.params.orderId) ? req.params.orderId[0] : req.params.orderId;
      this.cancelOrderUseCase.execute(orderId);
      res.status(204).send();
    } catch (error) {
      const message = error instanceof Error ? error.message : 'Unknown error';
      res.status(400).json({ error: message });
    }
  };

  listOrdersByState = (req: Request, res: Response): void => {
    try {
      const queryState = req.query.state as string | string[] | undefined;
      let state: string | undefined;
      if (Array.isArray(queryState)) {
        state = queryState[0];
      } else if (typeof queryState === 'string') {
        state = queryState;
      }

      if (!state || !['placed', 'paid', 'packed', 'shipped', 'delivered'].includes(state)) {
        res.status(400).json({ error: 'Invalid state' });
        return;
      }

      const response = this.listOrdersByStateUseCase.execute(state as OrderState);
      res.json(response);
    } catch (error) {
      const message = error instanceof Error ? error.message : 'Unknown error';
      res.status(400).json({ error: message });
    }
  };
}

